INSERT INTO `news` VALUES (4,'whx-dubai-2026-basladi','WHX Dubai 2026 Başladı!','WHX Dubai 2026 Has Started!','بدأ معرض WHX دبي 2026!','assets/images/632243921_18184992346362671_1920490016203500309_n.jpg',NULL,'Seyitler Kimya A.Ş. olarak, dünyanın en büyük sağlık ve medikal fuarlarından biri olan World Health Expo (WHX) Dubai 2026’da yerimizi aldık! 9–12 Şubat 2026 tarihleri arasında Dubai Exhibition Centre’da, yenilikçi ürünlerimiz ve çözümlerimizle sizleri standımızda ağırlamaktan memnuniyet duyacağız.','As Seyitler Kimya A.Ş., we took our place at World Health Expo (WHX) Dubai 2026! We will be glad to welcome you at our booth with our innovative healthcare solutions.','بصفتنا شركة سييتلر كيميا، اتخذنا مكاننا في معرض الصحة العالمي (WHX) دبي 2026! يسعدنا الترحيب بكم في جناحنا بحلولنا المبتكرة في الرعاية الصحية.','https://www.instagram.com/p/DUkhTXXjZhO/?img_index=1&igsh=bTdseWttMHZtYzA4','Fuar & Etkinlik','Expo & Event','معارض وفعاليات','09.02.2026',1,1,'2026-09-03 20:35:42'),(5,'seyitler-kimya-whx-dubai-2026da','Seyitler Kimya, WHX Dubai 2026’da!','Seyitler Kimya at WHX Dubai 2026!','سييتلر كيميا في معرض WHX دبي 2026!','assets/images/612981521_18181607563362671_6438164751575343459_n.jpg',NULL,'Dünyanın en büyük sağlık ve medikal fuarlarından biri olan WHX Dubai 2026 (World Health Expo)’da yenilikçi ürünlerimiz ve global vizyonumuzla yer alacağız.','We will take part in WHX Dubai 2026, one of the world\'s largest medical expos, showcasing our innovative medical products and global vision.','سنشارك في معرض WHX دبي 2026 كأحد أكبر معارض الصحة العالمية لنعرض منتجاتنا المبتكرة ورؤيتنا العالمية.','https://www.instagram.com/p/DTSed4qjMG2/','Duyuru','Announcement','إعلان','25.01.2026',1,2,'2026-09-03 20:35:42'),(6,'health-expo-irak-bagdat','Health Expo Irak Bağdat – Uluslararası Sağlık, Medikal ve Eczacılık Fuarı','Health Expo Iraq Baghdad – International Health & Medical Expo','معرض الصحة الدولي بغداد - العراق','assets/images/588618600_18178643221362671_320769796744369809_n.jpg',NULL,'Irak’ın Bağdat kentinde düzenlenen Health Expo – Uluslararası Sağlık, Medikal ve Eczacılık Fuarı’na dair standımızı ve paylaşımlarımızı keşfedin.','Discover our presence and medical portfolio at Health Expo Baghdad in Iraq.','اكتشف جناحنا ومجموعتنا الطبية في معرض الصحة الدولي في بغداد بالعراق.','https://www.instagram.com/p/DSAbL5MDBi4/?img_index=1','Uluslararası Fuar','International Expo','معرض دولي','15.12.2025',1,3,'2026-09-03 20:35:42'),(7,'seyitler-kimya-medica-dusseldorf-2025te','Seyitler Kimya, MEDICA Düsseldorf 2025’te!','Seyitler Kimya at MEDICA Düsseldorf 2025!','سييتلر كيميا في معرض ميديكا دوسلدورف 2025!','assets/images/572597020_18176378665362671_4920280767549128056_n.jpg',NULL,'Dünyanın en büyük medikal fuarlarından biri olan MEDICA Düsseldorf 2025’te yer alacağımızı gururla duyuruyoruz.','We proudly announce our participation in MEDICA Düsseldorf 2025, one of the world\'s premiere healthcare exhibitions.','نعلن بفخر عن مشاركتنا في معرض ميديكا دوسلدورف 2025، أحد أكبر المعارض الطبية في العالم.','https://www.instagram.com/p/DQ_s48mDFbs/','Almanya Fuarı','Germany Expo','معرض ألمانيا','17.11.2025',1,4,'2026-09-03 20:35:42'),(8,'yeni-ar-ge-yatirimi-seyka-saglik-teknolojileri','Seyitler Kimya\'dan Yeni Ar-Ge Yatırımı: Seyka Sağlık Teknolojileri','New R&D Investment from Seyitler Kimya: Seyka Health Technologies','استثمار جديد في البحث والتطوير: سييكا للتكنولوجيا الصحية','assets/images/1766047162027.jpeg',NULL,'Seyitler Kimya A.Ş. olarak, Ege Üniversitesi Teknopark bünyesinde kurulan Ar-Ge şirketimiz Seyka Sağlık Teknolojileri San. Tic. A.Ş. ile bilim, teknoloji ve yenilik odaklı yolculuğumuzda yeni bir dönemi başlatıyoruz.','Seyitler Kimya launches a new era in healthcare innovation with our new R&D company Seyka Health Technologies at Ege University Technopark.','تبدأ سييتلر كيميا عصرًا جديدًا في الابتكار الصحي مع شركتنا الجديدة للبحث والتطوير سييكا في واحة العلوم بجامعة إيجه.','https://www.linkedin.com/posts/seyitler-kimya_seyitlerkimya-egeaesniversitesi-teknopark-activity-7407338679448375296--0Fv/','Ar-Ge Yatırımı','R&D Investment','استثمار في البحث والتطوير','05.10.2025',1,5,'2026-09-03 20:35:42'),(9,'seyitler-kimya-35-yilinda-gelecege-hazirlaniyor','Seyitler Kimya 35. Yılında Geleceğe Hazırlanıyor','Seyitler Kimya Prepares for the Future on its 35th Anniversary','سييتلر كيميا تستعد للمستقبل في عامها الخامس والثلاثين',NULL,'https://dms.licdn.com/playlist/vid/v2/D4D05AQFIi7kKwlEjpw/mp4-720p-30fp-crf28/B4DZtaBPP1H4CI-/0/1766741836270?e=2147483647&v=beta&t=Y-oHc2fV1EWzqwbiW8jK1vbKzW1UW1AWpcF4zYbo_Nk','1991’den bu yana sağlık sektöründe kalite, güven ve sürdürülebilir üretim anlayışıyla yol alan Seyitler Kimya, 35. kuruluş yılında yenilenen ürün portföyü ve güçlü Ar-Ge altyapısıyla yeni bir büyüme dönemine adım atıyor.','Advancing with quality and trust since 1991, Seyitler Kimya steps into a new growth era on its 35th year.','تتقدم سييتلر كيميا بالجودة والثقة منذ عام 1991، وتدخل مرحلة نمو جديدة في عامها الخامس والثلاثين.','https://www.linkedin.com/posts/seyitler-kimya_seyitlerkimya-35yaftl-saafblaftksektaemraes-activity-7410252360305856512-t6BK/','35. Yıl Vizyonu','35th Year Vision','رؤية 35 عاماً','01.09.2025',1,6,'2026-09-03 20:35:42'),(10,'seyitler-kimyadan-yeni-urun-silionyx','Seyitler Kimya’den Yeni Ürün: SILIONYX','New Breakthrough Product from Seyitler Kimya: SILIONYX','منتج متطور جديد من سييتلر كيميا: SILIONYX',NULL,'https://dms.licdn.com/playlist/vid/v2/D4D05AQHDuKEWr0ne5A/mp4-720p-30fp-crf28/B4DZwEFHb1JcCE-/0/1769594978812?e=2147483647&v=beta&t=W1rpMKJNGFyWbqmgx_5TQ_6OgBnMLw3b_uFIYXNDeDc','Seyitler Kimya olarak, yara izi bakımı ve cilt onarımına yönelik ürün portföyümüze yeni nesil bir çözüm ekliyoruz. SILIONYX Silikon Jel Flaster, cerrahi izler ve skar dokusunun görünümünü azaltmaya yardımcı olmak üzere geliştirilmiştir.','SILIONYX Silicone Gel Plaster is developed to improve the appearance of surgical scars and scar tissue with premium medical grade silicone.','تم تطوير لاصق جل السيليكون SILIONYX للمساعدة في تحسين مظهر الندبات الجراحية وأنسجة الندوب.','https://www.linkedin.com/posts/seyitler-kimya_seyitlerkimya-silionyx-yeniaesraesn-activity-7422219326625296385-u99m/','Yeni Ürün','New Product','منتج جديد','20.08.2025',1,7,'2026-09-03 20:35:42');
