INSERT INTO `pages` VALUES (1,'about-us','Hakkımızda','About Us','من نحن','Sağlıkta Güvenin Global Adı','The Global Name of Trust in Healthcare','الاسم العالمي للثقة في الرعاية الصحية','<p>1991 yılından bu yana sağlık sektöründe üretim gücümüzü kalite anlayışımızla birleştirerek Türkiye’nin en köklü ve en güçlü medikal üretim tesislerinden biri olmanın gururunu yaşıyoruz. Seyitler Kimya Sanayi A.Ş. olarak, Manisa’daki merkez üretim kampüsümüzde, 17.257 m² kapalı alanda faaliyet gösteriyor; alanında uzman çalışanımız ile yüksek hacimli siparişleri karşılayabilecek altyapımız sayesinde üretimde sürekliliği, verimliliği ve güvenilirliği bir arada sunuyoruz.</p><p>Ürün portföyümüzde plasterler, yara örtüleri, ilk yardım bantları, katı tıbbi yara ürünleri ve plaster-yakı grubu yer alıyor; bu alanlarda Türkiye’de sektör lideri konumunda bulunuyoruz. Toplamda 30 farklı ürün üretirken bunların 17’sini, kendi markalarımız altında pazara sunuyoruz.</p>','<p>1991 yılından bu yana sağlık sektöründe üretim gücümüzü kalite anlayışımızla birleştirerek Türkiye’nin en köklü ve en güçlü medikal üretim tesislerinden biri olmanın gururunu yaşıyoruz. Seyitler Kimya Sanayi A.Ş. olarak, Manisa’daki merkez üretim kampüsümüzde, 17.257 m² kapalı alanda faaliyet gösteriyor; alanında uzman çalışanımız ile yüksek hacimli siparişleri karşılayabilecek altyapımız sayesinde üretimde sürekliliği, verimliliği ve güvenilirliği bir arada sunuyoruz.</p><p>Ürün portföyümüzde plasterler, yara örtüleri, ilk yardım bantları, katı tıbbi yara ürünleri ve plaster-yakı grubu yer alıyor; bu alanlarda Türkiye’de sektör lideri konumunda bulunuyoruz. Toplamda 30 farklı ürün üretirken bunların 17’sini, kendi markalarımız altında pazara sunuyoruz.</p>','<p>1991 yılından bu yana sağlık sektöründe üretim gücümüzü kalite anlayışımızla birleştirerek Türkiye’nin en köklü ve en güçlü medikal üretim tesislerinden biri olmanın gururunu yaşıyoruz. Seyitler Kimya Sanayi A.Ş. olarak, Manisa’daki merkez üretim kampüsümüzde, 17.257 m² kapalı alanda faaliyet gösteriyor; alanında uzman çalışanımız ile yüksek hacimli siparişleri karşılayabilecek altyapımız sayesinde üretimde sürekliliği, verimliliği ve güvenilirliği bir arada sunuyoruz.</p><p>Ürün portföyümüzde plasterler, yara örtüleri, ilk yardım bantları, katı tıbbi yara ürünleri ve plaster-yakı grubu yer alıyor; bu alanlarda Türkiye’de sektör lideri konumunda bulunuyoruz. Toplamda 30 farklı ürün üretirken bunların 17’sini, kendi markalarımız altında pazara sunuyoruz.</p>','assets/images/hakkimizda_01.webp','Hakkımızda - Seyitler Kimya',NULL,NULL,'1991 yılından bu yana sağlık sektöründe üretim gücümüzü kalite anlayışımızla birleştirerek Türkiye’nin en köklü medikal üretim tesislerinden biri olmanın gururunu yaşıyoruz.',NULL,NULL,1,'2026-09-03 15:53:38'),(2,'history','Tarihçe','History','تاريخنا','Geçmişten Geleceğe Sağlık Yolculuğu','Healthcare Journey from Past to Future','رحلة الرعاية الصحية من الماضي إلى المستقبل','<p>Seyitler Kimya, 1991 yılında medikal yapışkan ve plaster üretimiyle başladığı yolculuğunda bugün uluslararası standartlarda üretim yapan modern tesislere ulaşmıştır. 35 yıllık tecrübemizle Türk sağlık sektörünün öncülerinden biri olmanın gururunu taşıyoruz.</p>','<p>Seyitler Kimya, 1991 yılında medikal yapışkan ve plaster üretimiyle başladığı yolculuğunda bugün uluslararası standartlarda üretim yapan modern tesislere ulaşmıştır. 35 yıllık tecrübemizle Türk sağlık sektörünün öncülerinden biri olmanın gururunu taşıyoruz.</p>','<p>Seyitler Kimya, 1991 yılında medikal yapışkan ve plaster üretimiyle başladığı yolculuğunda bugün uluslararası standartlarda üretim yapan modern tesislere ulaşmıştır. 35 yıllık tecrübemizle Türk sağlık sektörünün öncülerinden biri olmanın gururunu taşıyoruz.</p>','assets/images/Seyitker_Anasayfa_03-min.webp','Tarihçe - Seyitler Kimya',NULL,NULL,'Seyitler Kimya Sanayi A.Ş. kuruluşundan bugüne uzanan başarı dolu medikal üretim yolculuğu.',NULL,NULL,1,'2026-09-03 15:53:38'),(3,'mission-vision','Misyon ve Vizyon','Mission & Vision','مهمتنا ورؤيتنا','Değer Katan Hedefler ve Gelecek Vizyonumuz','Value-Adding Goals & Future Vision','أهداف ذات قيمة ورؤيتنا للمستقبل','<h3>Misyonumuz</h3><p>Sağlık sektöründe güvenilir ve kaliteli ürünler üreterek yaşamınıza değer katıyoruz. Paydaşlarımızla sürdürülebilir ilişkiler kurarken üretim süreçlerimizde şeffaflık, etik sorumluluk ve sürekli gelişim ilkelerinden ödün vermiyoruz.</p><h3>Vizyonumuz</h3><p>Medikal üretim alanında yeniliği, kaliteyi ve güveni temsil eden global bir marka olmak, Ar-Ge ve inovasyona dayalı üretim anlayışımızla geleceğin tedavi çözümlerini geliştirmek.</p>','<h3>Misyonumuz</h3><p>Sağlık sektöründe güvenilir ve kaliteli ürünler üreterek yaşamınıza değer katıyoruz. Paydaşlarımızla sürdürülebilir ilişkiler kurarken üretim süreçlerimizde şeffaflık, etik sorumluluk ve sürekli gelişim ilkelerinden ödün vermiyoruz.</p><h3>Vizyonumuz</h3><p>Medikal üretim alanında yeniliği, kaliteyi ve güveni temsil eden global bir marka olmak, Ar-Ge ve inovasyona dayalı üretim anlayışımızla geleceğin tedavi çözümlerini geliştirmek.</p>','<h3>Misyonumuz</h3><p>Sağlık sektöründe güvenilir ve kaliteli ürünler üreterek yaşamınıza değer katıyoruz. Paydaşlarımızla sürdürülebilir ilişkiler kurarken üretim süreçlerimizde şeffaflık, etik sorumluluk ve sürekli gelişim ilkelerinden ödün vermiyoruz.</p><h3>Vizyonumuz</h3><p>Medikal üretim alanında yeniliği, kaliteyi ve güveni temsil eden global bir marka olmak, Ar-Ge ve inovasyona dayalı üretim anlayışımızla geleceğin tedavi çözümlerini geliştirmek.</p>','assets/images/misyonumuz-min.webp','Misyon ve Vizyon - Seyitler Kimya',NULL,NULL,'İnsan sağlığına değer katan kaliteli medikal ürünler üretmek ve sektörde küresel standartları belirlemek.',NULL,NULL,1,'2026-09-03 15:53:38'),(4,'values','Değerlerimiz','Our Values','قيمنا','Bizi Biz Yapan Kurumsal İlkeler','Corporate Principles That Define Us','المبادئ المؤسسية التي تحددنا','<p>Güvenilirlik, Şeffaflık, İnovasyon ve Kalitede Süreklilik temel kurumsal değerlerimizdir. Her aşamada hasta sağlığı ve iş ortağı memnuniyetini en üst seviyede tutmayı taahhüt ediyoruz.</p>','<p>Güvenilirlik, Şeffaflık, İnovasyon ve Kalitede Süreklilik temel kurumsal değerlerimizdir. Her aşamada hasta sağlığı ve iş ortağı memnuniyetini en üst seviyede tutmayı taahhüt ediyoruz.</p>','<p>Güvenilirlik, Şeffaflık, İnovasyon ve Kalitede Süreklilik temel kurumsal değerlerimizdir. Her aşamada hasta sağlığı ve iş ortağı memnuniyetini en üst seviyede tutmayı taahhüt ediyoruz.</p>','assets/images/Seyitker_Anasayfa_02-min.webp','Değerlerimiz - Seyitler Kimya',NULL,NULL,'Güven, Kalite, Şeffaflık, Yenilik, İnsan Odaklılık ve Sürdürülebilirlik ilkelerimizle büyüyoruz.',NULL,NULL,1,'2026-09-03 15:53:38'),(5,'organization','Organizasyon Şeması','Organizational Structure','الهيكل التنظيمي','Güçlü Yönetim ve Uzman Kadro','Strong Governance & Expert Workforce','إدارة قوية وقوى عاملة متخصصة','<p>Yönetim Kurulumuz, İcra Kurulu ve uzman teknik kadrolarımızla şeffaf ve kurumsal yönetim ilkeleri doğrultusunda yönetilmektedir.</p>','<p>Yönetim Kurulumuz, İcra Kurulu ve uzman teknik kadrolarımızla şeffaf ve kurumsal yönetim ilkeleri doğrultusunda yönetilmektedir.</p>','<p>Yönetim Kurulumuz, İcra Kurulu ve uzman teknik kadrolarımızla şeffaf ve kurumsal yönetim ilkeleri doğrultusunda yönetilmektedir.</p>','assets/images/Seyitler_Anasayfa_Hakkimizda_v2.webp','Organizasyon Şeması - Seyitler Kimya',NULL,NULL,'Seyitler Kimya Yönetim Kurulu Başkanı mesajı ve kurumsal organizasyon şeması.',NULL,NULL,1,'2026-09-03 15:53:38'),(6,'sustainability','Sürdürülebilirlik','Sustainability','الاستدامة','Gelecek Nesillere Saygılı Üretim','Responsible Manufacturing for Future Generations','التصنيع المسؤول للأجيال القادمة','<p>Sıfır atık, enerji verimliliği ve çevre dostu ambalajlama standartlarımızla gezegenimizin geleceğini koruyarak üretim yapıyoruz.</p>','<p>Sıfır atık, enerji verimliliği ve çevre dostu ambalajlama standartlarımızla gezegenimizin geleceğini koruyarak üreti