INSERT INTO `products` VALUES (1,1,'dermafix-plus','Dermafix Plus','Dermafix Plus','Dermafix Plus','Tıbbi cihazların sabitlenmesi ve pansumanların tespiti için hipoalerjenik yapışkanlı şeffaf cerrahi bant.','Hypoallergenic adhesive transparent surgical tape for fixing medical devices and dressings.','شريط جراحي شفاف لا يسبب الحساسية لتثبيت الأجهزة الطبية والضمادات.','[\"Şeffaf, gözenekli polietilen taşıyıcı\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Hava ve neme geçirgen\", \"Kolay, düz ve çift yönlü yırtılabilir\", \"Suya dayanıklı\", \"Radyotransparan\"]','[\"Şeffaf, gözenekli polietilen taşıyıcı\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Hava ve neme geçirgen\", \"Kolay, düz ve çift yönlü yırtılabilir\", \"Suya dayanıklı\", \"Radyotransparan\"]','[\"Şeffaf, gözenekli polietilen taşıyıcı\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Hava ve neme geçirgen\", \"Kolay, düz ve çift yönlü yırtılabilir\", \"Suya dayanıklı\", \"Radyotransparan\"]','assets/images/TibbiPlasterler/Derma_fix/Derma_fix.webp','[\"assets/images/TibbiPlasterler/Derma_fix/Derma_fix.webp\"]',1,13,'2026-09-02 11:22:43'),(2,1,'dermapore-band','Derma Pore','Derma Pore','Derma Pore','Tıbbi cihazların sabitlenmesi ve pansumanların tespiti için hipoalerjenik yapışkanlı kağıt cerrahi bant.','Hypoallergenic adhesive paper surgical tape for fixing medical devices and dressings.','شريط جراحي ورقي لا يسبب الحساسية لتثبيت الأجهزة الطبية والضمادات.','[\"Polyester viskon non-woven taşıyıcı\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Hava ve neme geçirgen\", \"Vücudun kıvrımlı bölgelerinde dahi yüksek uyum\", \"Radyotransparan\"]','[\"Polyester viskon non-woven taşıyıcı\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Hava ve neme geçirgen\", \"Vücudun kıvrımlı bölgelerinde dahi yüksek uyum\", \"Radyotransparan\"]','[\"Polyester viskon non-woven taşıyıcı\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Hava ve neme geçirgen\", \"Vücudun kıvrımlı bölgelerinde dahi yüksek uyum\", \"Radyotransparan\"]','assets/images/TibbiPlasterler/Derma_pore/Derma_pore.webp','[\"assets/images/TibbiPlasterler/Derma_pore/Derma_pore.webp\", \"assets/images/TibbiPlasterler/Derma_pore/Derma_pore_Galeri_01.webp\", \"assets/images/TibbiPlasterler/Derma_pore/Derma_pore_Galeri_02.webp\", \"assets/images/TibbiPlasterler/Derma_pore/Derma_pore_Galeri_03.webp\", \"assets/images/TibbiPlasterler/Derma_pore/Derma_pore_Galeri_04.webp\", \"assets/images/TibbiPlasterler/Derma_pore/Derma_pore_Galeri_05.webp\", \"assets/images/TibbiPlasterler/Derma_pore/Derma_pore_Galeri_06.webp\"]',1,17,'2026-09-02 11:22:43'),(3,3,'maxipore-dress','Maxipore Dress','Maxipore Dress','Maxipore Dress','Nonwoven taşıyıcılı, non-adherent yara pedi bulunan post-operatif pansuman.','Post-operative dressing with nonwoven backing and non-adherent wound pad.','ضمادة ما بعد الجراحة بحامل غير منسوج ووسادة جروح غير لاصقة.','[\"Nonwoven taşıyıcı ve yapışmayan yara pedi\", \"Hava ve su buharına yüksek geçirgenlik\", \"Yumuşak ve cilde uyumlu nonwoven yapı, hipoalerjenik\", \"Kolay uygulanabilir\", \"Steril\"]','[\"Nonwoven taşıyıcı ve yapışmayan yara pedi\", \"Hava ve su buharına yüksek geçirgenlik\", \"Yumuşak ve cilde uyumlu nonwoven yapı, hipoalerjenik\", \"Kolay uygulanabilir\", \"Steril\"]','[\"Nonwoven taşıyıcı ve yapışmayan yara pedi\", \"Hava ve su buharına yüksek geçirgenlik\", \"Yumuşak ve cilde uyumlu nonwoven yapı, hipoalerjenik\", \"Kolay uygulanabilir\", \"Steril\"]','assets/images/YaraBakim/Maxipore_Dress/Maxipore_Dress.webp','[\"assets/images/YaraBakim/Maxipore_Dress/Maxipore_Dress.webp\", \"assets/images/YaraBakim/Maxipore_Dress/Maxipore_Dress_Galeri_01.webp\", \"assets/images/YaraBakim/Maxipore_Dress/Maxipore_Dress_Galeri_02.webp\", \"assets/images/YaraBakim/Maxipore_Dress/Maxipore_Dress_Galeri_03.webp\", \"assets/images/YaraBakim/Maxipore_Dress/Maxipore_Dress_Galeri_04.webp\", \"assets/images/YaraBakim/Maxipore_Dress/Maxipore_Dress_Galeri_05.webp\"]',1,9,'2026-09-02 11:22:43'),(4,3,'maxipore-iv-nonwoven','Maxipore I.V. (Nonwoven)','Maxipore I.V. (Nonwoven)','Maxipore I.V. (Nonwoven)','Nonwoven I.V. plaster, non-adherent ped ile I.V. ve santral kateter tespiti için kullanılır.','Nonwoven I.V. plaster with non-adherent pad used for securing I.V. and central catheters.','لاصق I.V. غير منسوج مع وسادة غير لاصقة لتثبيت القسطرة الوريدية والمركزية.','[\"Nonwoven taşıyıcı ve yapışmayan yara pedi\", \"Elastik nonwoven, vücut konturuna uyum sağlar\", \"Kolay uygulanabilir tasarım\", \"Steril\"]','[\"Nonwoven taşıyıcı ve yapışmayan yara pedi\", \"Elastik nonwoven, vücut konturuna uyum sağlar\", \"Kolay uygulanabilir tasarım\", \"Steril\"]','[\"Nonwoven taşıyıcı ve yapışmayan yara pedi\", \"Elastik nonwoven, vücut konturuna uyum sağlar\", \"Kolay uygulanabilir tasarım\", \"Steril\"]','assets/images/YaraBakim/Maxipore_IV_Nonwoven.webp','[\"assets/images/YaraBakim/Maxipore_IV_Nonwoven.webp\"]',1,7,'2026-09-02 11:22:43'),(5,3,'maxipore-pu-dress','Maxipore PU Dress','Maxipore PU Dress','Maxipore PU Dress','Şeffaf film taşıyıcılı, non-adherent pedli post-operatif yara örtüsü.','Post-operative wound dressing with transparent film backing and non-adherent pad.','غطاء جروح ما بعد الجراحة بحامل فيلم شفاف ووسادة غير لاصقة.','[\"Hareketle uyumlu, su geçirmez şeffaf film ve non-adherent ped\", \"Nem buharı ve oksijen geçişi ile cildin normal fonksiyonunu destekler\", \"Bakteri ve virüslere karşı etkili bariyer\", \"Yumuşak ve cilde uyumlu, hipoalerjenik\", \"Kolay uygulanabilir\", \"Steril\"]','[\"Hareketle uyumlu, su geçirmez şeffaf film ve non-adherent ped\", \"Nem buharı ve oksijen geçişi ile cildin normal fonksiyonunu destekler\", \"Bakteri ve virüslere karşı etkili bariyer\", \"Yumuşak ve cilde uyumlu, hipoalerjenik\", \"Kolay uygulanabilir\", \"Steril\"]','[\"Hareketle uyumlu, su geçirmez şeffaf film ve non-adherent ped\", \"Nem buharı ve oksijen geçişi ile cildin normal fonksiyonunu destekler\", \"Bakteri ve virüslere karşı etkili bariyer\", \"Yumuşak ve cilde uyumlu, hipoalerjenik\", \"Kolay uygulanabilir\", \"Steril\"]','assets/images/YaraBakim/Maxipore_PU_Dress/Maxipore_PU_Dress.webp','[\"assets/images/YaraBakim/Maxipore_PU_Dress/Maxipore_PU_Dress.webp\", \"assets/images/YaraBakim/Maxipore_PU_Dress/Maxipore_PU_Dress_Galeri_01.webp\", \"assets/images/YaraBakim/Maxipore_PU_Dress/Maxipore_PU_Dress_Galeri_02.webp\", \"assets/images/YaraBakim/Maxipore_PU_Dress/Maxipore_PU_Dress_Galeri_03.webp\", \"assets/images/YaraBakim/Maxipore_PU_Dress/Maxipore_PU_Dress_Galeri_04.webp\", \"assets/images/YaraBakim/Maxipore_PU_Dress/Maxipore_PU_Dress_Galeri_05.webp\"]',1,10,'2026-09-02 11:22:43'),(6,3,'maxipore-pu-film','Maxipore PU Film','Maxipore PU Film','Maxipore PU Film','I.V. kateter bölgelerini ve yaraları korumak, cilt üzerine cihaz tespiti ve nemli iyileşme ortamı sağlamak için şeffaf film örtü.','Transparent film dressing to protect I.V. catheter sites and wounds, secure devices, and provide a moist healing environment.','غطاء فيلم شفاف لحماية مواقع قسطرة I.V. والجروح وتثبيت الأجهزة وتوفير بيئة رطبة للشفاء.','[\"Hareketle uyumlu, nem yönetimi sağlayan su geçirmez şeffaf film\", \"Sıvılar, bakteriler ve virüslere karşı su geçirmez, steril bariyer\", \"Sürekli görünürlük sağlar\", \"Yumuşak ve vücuda uyumlu, ciltle uyumlu ve hipoalerjenik\", \"Resim çerçevesi tasarımı ile kolay uygulama\", \"Steril\"]','[\"Hareketle uyumlu, nem yönetimi sağlayan su geçirmez şeffaf film\", \"Sıvılar, bakteriler ve virüslere karşı su geçirmez, steril bariyer\", \"Sürekli görünürlük sağlar\", \"Yumuşak ve vücuda uyumlu, ciltle uyumlu ve hipoalerjenik\", \"Resim çerçevesi tasarımı ile kolay uygulama\", \"Steril\"]','[\"Hareketle uyumlu, nem yönetimi sağlayan su geçirmez şeffaf film\", \"Sıvılar, bakteriler ve virüslere karşı su geçirmez, steril bariyer\", \"Sürekli görünürlük sağlar\", \"Yumuşak ve vücuda uyumlu, ciltle uyumlu ve hipoalerjenik\", \"Resim çerçevesi tasarımı ile kolay uygulama\", \"Steril\"]','assets/images/YaraBakim/Maxipore_PU_Film.webp','[\"assets/images/YaraBakim/Maxipore_PU_Film.webp\"]',1,11,'2026-09-02 11:22:43'),(7,3,'maxipore-pu-iv','Maxipore PU I.V.','Maxipore PU I.V.','Maxipore PU I.V.','Şeffaf I.V. plaster, I.V. ve santral kateter tespiti için suya dayanıklı film plaster.','Transparent I.V. plaster, waterproof film plaster for securing I.V. and central catheters.','لاصق I.V. شفاف مقاوم للماء لتثبيت القسطرة الوريدية والمركزية.','[\"Hareketle uyumlu, su geçirmez şeffaf film taşıyıcı\", \"Sıvılar ve bakteriler dahil dış etkenlere karşı bariyer\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Resim çerçeveli tasarım ile kolay uygulama\", \"Steril\"]','[\"Hareketle uyumlu, su geçirmez şeffaf film taşıyıcı\", \"Sıvılar ve bakteriler dahil dış etkenlere karşı bariyer\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Resim çerçeveli tasarım ile kolay uygulama\", \"Steril\"]','[\"Hareketle uyumlu, su geçirmez şeffaf film taşıyıcı\", \"Sıvılar ve bakteriler dahil dış etkenlere karşı bariyer\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Resim çerçeveli tasarım ile kolay uygulama\", \"Steril\"]','assets/images/YaraBakim/Maxipore_PU_IV.webp','[\"assets/images/YaraBakim/Maxipore_PU_IV.webp\"]',1,8,'2026-09-02 11:22:43'),(8,3,'maxipore-pu-roll','Maxipore PU Roll','Maxipore PU Roll','Maxipore PU Roll','Tıbbi cihazların sabitlenmesi ve pansumanların tespiti için hipoalerjenik yapışkanlı şeffaf film rulo.','Hypoallergenic adhesive transparent film roll for fixing medical devices and securing dressings.','لفة فيلم شفاف لا تسبب الحساسية لتثبيت الأجهزة الطبية وتأمين الضمادات.','[\"Hareketle uyumlu, nem yönetimi sağlayan şeffaf su geçirmez film\", \"Sıvılar, bakteriler ve virüslere karşı bariyer sağlar\", \"Sürekli görünürlük sunar\", \"Yumuşak ve vücuda uyumlu, ciltle uyumlu ve hipoalerjenik\", \"İstenilen boyda kesilerek kullanılabilir\", \"Kolay uygulanabilir\"]','[\"Hareketle uyumlu, nem yönetimi sağlayan şeffaf su geçirmez film\", \"Sıvılar, bakteriler ve virüslere karşı bariyer sağlar\", \"Sürekli görünürlük sunar\", \"Yumuşak ve vücuda uyumlu, ciltle uyumlu ve hipoalerjenik\", \"İstenilen boyda kesilerek kullanılabilir\", \"Kolay uygulanabilir\"]','[\"Hareketle uyumlu, nem yönetimi sağlayan şeffaf su geçirmez film\", \"Sıvılar, bakteriler ve virüslere karşı bariyer sağlar\", \"Sürekli görünürlük sunar\", \"Yumuşak ve vücuda uyumlu, ciltle uyumlu ve hipoalerjenik\", \"İstenilen boyda kesilerek kullanılabilir\", \"Kolay uygulanabilir\"]','assets/images/main/Maxipore_PuRoll_Web_01.jpg','[\"assets/images/main/Maxipore_PuRoll_Web_01.jpg\", \"assets/images/main/Maxipore_PuRoll_Web_02.jpg\", \"assets/images/main/Maxipore_PuRoll_Web_03.jpg\", \"assets/images/main/Maxipore_PuRoll_Web_04.jpg\"]',1,12,'2026-09-02 11:22:43'),(9,1,'medi-bez-plaster','Medi-Bez Plaster','Medi-Bez Plaster','Medi-Bez Plaster','Tıbbi cihazların sabitlenmesi ve pansumanların tespiti için pamuklu kumaş cerrahi bant.','Cotton fabric surgical tape for fixing medical devices and securing dressings.','شريط جراحي قماشي قطني لتثبيت الأجهزة الطبية وتأمين الضمادات.','[\"Pamuklu kumaş taşıyıcı\", \"Güçlü yapışma\", \"Güçlü, güvenilir sabitleme\", \"Cilt dostu yapışkan\", \"Radyotransparan\"]','[\"Pamuklu kumaş taşıyıcı\", \"Güçlü yapışma\", \"Güçlü, güvenilir sabitleme\", \"Cilt dostu yapışkan\", \"Radyotransparan\"]','[\"Pamuklu kumaş taşıyıcı\", \"Güçlü yapışma\", \"Güçlü, güvenilir sabitleme\", \"Cilt dostu yapışkan\", \"Radyotransparan\"]','assets/images/TibbiPlasterler/Medi_bez/Medi_bez.webp','[\"assets/images/TibbiPlasterler/Medi_bez/Medi_bez.webp\", \"assets/images/TibbiPlasterler/Medi_bez/Medi_bez_Galeri_01.webp\", \"assets/images/TibbiPlasterler/Medi_bez/Medi_bez_Galeri_02.webp\", \"assets/images/TibbiPlasterler/Medi_bez/Medi_bez_Galeri_03.webp\", \"assets/images/TibbiPlasterler/Medi_bez/Medi_bez_Galeri_04.webp\", \"assets/images/TibbiPlasterler/Medi_bez/Medi_bez_Galeri_05.webp\", \"assets/images/TibbiPlasterler/Medi_bez/Medi_bez_Galeri_06.webp\", \"assets/images/TibbiPlasterler/Medi_bez/Medi_bez_Galeri_07.webp\"]',1,14,'2026-09-02 11:22:43'),(10,1,'medi-ipek-flaster','Medi İpek Plaster','Medi İpek Plaster','Medi İpek Plaster','Tıbbi cihazların sabitlenmesi ve pansumanların tespiti için cerrahi ipek bant.','Surgical silk tape for fixing medical devices and securing dressings.','شريط حريري جراحي لتثبيت الأجهزة الطبية وتأمين الضmادات.','[\"İpek asetat kumaş taşıyıcı\", \"Güçlü yapışma, elle kolayca yırtılabilir\", \"Güçlü, güvenilir sabitleme\", \"Cilt dostu yapışkan\", \"Radyotransparan\"]','[\"İpek asetat kumaş taşıyıcı\", \"Güçlü yapışma, elle kolayca yırtılabilir\", \"Güçlü, güvenilir sabitleme\", \"Cilt dostu yapışkan\", \"Radyotransparan\"]','[\"İpek asetat kumaş taşıyıcı\", \"Güçlü yapışma, elle kolayca yırtılabilir\", \"Güçlü, güvenilir sabitleme\", \"Cilt dostu yapışkan\", \"Radyotransparan\"]','assets/images/TibbiPlasterler/Medi_ipek/Medi_ipek.webp','[\"assets/images/TibbiPlasterler/Medi_ipek/Medi_ipek.webp\", \"assets/images/TibbiPlasterler/Medi_ipek/Medi_ipek_Galeri_01.webp\", \"assets/images/TibbiPlasterler/Medi_ipek/Medi_ipek_Galeri_02.webp\", \"assets/images/TibbiPlasterler/Medi_ipek/Medi_ipek_Galeri_03.webp\", \"assets/images/TibbiPlasterler/Medi_ipek/Medi_ipek_Galeri_04.webp\", \"assets/images/TibbiPlasterler/Medi_ipek/Medi_ipek_Galeri_05.webp\", \"assets/images/TibbiPlasterler/Medi_ipek/Medi_ipek_Galeri_06.webp\", \"assets/images/TibbiPlasterler/Medi_ipek/Medi_ipek_Galeri_07.webp\"]',1,16,'2026-09-02 11:22:43'),(11,6,'nova-dialysis-basi-bandi','Nova Dialysis Bası Bandı','Nova Dialysis Bası Bandı','Nova Dialysis Bası Bandı','Hemodiyaliz sonrası ve kanamanın devam ettiği enjeksiyonlarda kullanılan hemostatik bası bandajı.','Hemostatic pressure bandage used after hemodialysis and injections where bleeding continues.','ضمادة ضغط مرقئة تستخدم بعد غسيل الكلى وفي الحقن المستمرة النزيف.','[\"Ekstra emici bası pedi ile polietilen taşıyıcı\", \"Kanı emen ve kanamayı durdurmak için bası uygulayan ped\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Güçlü yapışkan ve sızdırmaz yapı\", \"Steril\"]','[\"Ekstra emici bası pedi ile polietilen taşıyıcı\", \"Kanı emen ve kanamayı durdurmak için bası uygulayan ped\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Güçlü yapışkan ve sızdırmaz yapı\", \"Steril\"]','[\"Ekstra emici bası pedi ile polietilen taşıyıcı\", \"Kanı emen ve kanamayı durdurmak için bası uygulayan ped\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Güçlü yapışkan ve sızdırmaz yapı\", \"Steril\"]','assets/images/HemostaticSerisi/Nova_Dialysis_Basi_Bandi.webp','[\"assets/images/HemostaticSerisi/Nova_Dialysis_Basi_Bandi.webp\", \"assets/images/HemostaticSerisi/Nova_Dialysis_Basi_Bandi_Galeri_01.webp\"]',1,6,'2026-09-02 11:22:43'),(12,1,'nova-fix','Nova Fix','Nova Fix','Nova Fix','Tıbbi cihazların ve pansumanların sabitlenmesi için elastik cerrahi plaster.','Elastic surgical plaster for fixing medical devices and dressings.','لاصق جراحي مرن لتثبيت الأجهزة الطبية والضمادات.','[\"Elastik nonwoven taşıyıcı\", \"Enine esneyebilir ve esnek yapı\", \"Vücut konturlarına uyum sağlar\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Hava ve neme geçirgen\", \"Radyolusent\"]','[\"Elastik nonwoven taşıyıcı\", \"Enine esneyebilir ve esnek yapı\", \"Vücut konturlarına uyum sağlar\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Hava ve neme geçirgen\", \"Radyolusent\"]','[\"Elastik nonwoven taşıyıcı\", \"Enine esneyebilir ve esnek yapı\", \"Vücut konturlarına uyum sağlar\", \"Hassas ciltler için nazik ve güvenli yapışma, hipoalerjenik\", \"Hava ve neme geçirgen\", \"Radyolusent\"]','assets/images/TibbiPlasterler/Nova_Fix/Nova_Fix.webp','[\"assets/images/TibbiPlasterler/Nova_Fix/Nova_Fix.webp\", \"assets/images/TibbiPlasterler/Nova_Fix/Nova_Fix_Galeri_0